CREATE TABLE IF NOT EXISTS "cat_task" (
    "id" bigint NOT NULL,
    "source_system_id" bigint,
    "source_system_name" character varying,
    "name" character varying NOT NULL,
    "datasource_id" bigint NOT NULL,
    "db_type" character varying NOT NULL,
    "leader" bigint,
    "leader_phone" character varying,
    "collection_mode" character varying NOT NULL DEFAULT '1'::character varying,
    "collection_scope" character varying NOT NULL DEFAULT '1'::character varying,
    "status" character varying NOT NULL DEFAULT '0'::character varying,
    "valid_flag" character varying NOT NULL DEFAULT '1'::character varying,
    "del_flag" character varying NOT NULL DEFAULT '0'::character varying,
    "create_by" character varying,
    "creator_id" bigint,
    "create_time" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "update_by" character varying,
    "updater_id" bigint,
    "update_time" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "remark" character varying,
    "description" character varying,
    "collect_type" smallint NOT NULL DEFAULT '1'::smallint,
    "blacklist" text,
    "responsible_dept" bigint,
    "space_code" character varying,
    "space_id" bigint
);

COMMENT ON TABLE "cat_task" IS 'cat_task';
COMMENT ON COLUMN "cat_task"."space_code" IS '项目编码';
COMMENT ON COLUMN "cat_task"."space_id" IS '项目ID';


