-- Comment: 探查任务-质量探查任务关联表
-- ============================================================
CREATE TABLE IF NOT EXISTS "cat_task_quality" (
    "id" bigint NOT NULL DEFAULT nextval('cat_task_quality_id_seq'::regclass),
    "cat_task_id" bigint NOT NULL,
    "quality_task_id" bigint NOT NULL,
    "create_by" character varying(64),
    "creator_id" bigint,
    "create_time" timestamp without time zone NOT NULL DEFAULT now(),
    "update_by" character varying(64),
    "updater_id" bigint,
    "update_time" timestamp without time zone,
    "remark" character varying(500),
    "del_flag" character varying(1) DEFAULT '0'::character varying,
    PRIMARY KEY ("id")
);

COMMENT ON TABLE "cat_task_quality" IS '探查任务-质量探查任务关联表';
COMMENT ON COLUMN "cat_task_quality"."cat_task_id" IS '探查任务ID（CAT_TASK.id）';
COMMENT ON COLUMN "cat_task_quality"."quality_task_id" IS '质量探查任务ID（COL_QUALITY_TASK.id）';

CREATE INDEX idx_cat_task_quality_cat ON public.cat_task_quality USING btree (cat_task_id);
CREATE INDEX idx_cat_task_quality_quality ON public.cat_task_quality USING btree (quality_task_id);

SELECT setval('cat_task_quality_id_seq', COALESCE((SELECT MAX("id") FROM "cat_task_quality"), 0) + 1, false);

