-- Comment: system_logininfor
-- ============================================================
CREATE TABLE IF NOT EXISTS "system_logininfor" (
    "info_id" bigint NOT NULL,
    "user_name" character varying DEFAULT ''::character varying,
    "ipaddr" character varying DEFAULT ''::character varying,
    "login_location" character varying DEFAULT ''::character varying,
    "browser" character varying DEFAULT ''::character varying,
    "os" character varying DEFAULT ''::character varying,
    "status" character(1) DEFAULT '0'::bpchar,
    "msg" character varying DEFAULT ''::character varying,
    "login_time" timestamp without time zone
);

COMMENT ON TABLE "system_logininfor" IS 'system_logininfor';


-- ============================================================
-- Table: system_menu (426 rows)
-- Comment: system_menu
-- ============================================================
CREATE TABLE IF NOT EXISTS "system_menu" (
    "menu_id" bigint NOT NULL,
    "menu_name" character varying NOT NULL,
    "parent_id" bigint DEFAULT '0'::bigint,
    "order_num" integer DEFAULT 0,
    "path" character varying DEFAULT ''::character varying,
    "component" character varying,
    "query" character varying,
    "is_frame" integer DEFAULT 1,
    "is_cache" integer DEFAULT 0,
    "route_name" character varying,
    "menu_type" character(1) DEFAULT ''::bpchar,
    "visible" character(1) DEFAULT '0'::bpchar,
    "status" character(1) DEFAULT '0'::bpchar,
    "perms" character varying,
    "icon" character varying DEFAULT '#'::character varying,
    "create_by" character varying DEFAULT ''::character varying,
    "create_time" timestamp without time zone,
    "update_by" character varying DEFAULT ''::character varying,
    "update_time" timestamp without time zone,
    "remark" character varying DEFAULT ''::character varying
);

COMMENT ON TABLE "system_menu" IS 'system_menu';


-- ============================================================
-- Table: system_oper_log (235 rows)
-- Comment: system_oper_log
-- ============================================================
CREATE TABLE IF NOT EXISTS "system_oper_log" (
    "oper_id" bigint NOT NULL DEFAULT nextval('system_oper_log_oper_id_seq'::regclass),
    "title" character varying DEFAULT ''::character varying,
    "business_type" integer DEFAULT 0,
    "method" character varying DEFAULT ''::character varying,
    "request_method" character varying DEFAULT ''::character varying,
    "operator_type" integer DEFAULT 0,
    "oper_name" character varying DEFAULT ''::character varying,
    "dept_name" character varying DEFAULT ''::character varying,
    "oper_url" character varying DEFAULT ''::character varying,
    "oper_ip" character varying DEFAULT ''::character varying,
    "oper_location" character varying DEFAULT ''::character varying,
    "oper_param" text,
    "json_result" text,
    "status" integer DEFAULT 0,
    "error_msg" character varying DEFAULT ''::character varying,
    "oper_time" timestamp without time zone,
    "cost_time" bigint DEFAULT '0'::bigint
);

COMMENT ON TABLE "system_oper_log" IS 'system_oper_log';

