INSERT INTO "ast_sensitive_level" ("id", "sensitive_level", "sensitive_rule", "start_char_loc", "end_char_loc", "mask_character", "online_flag", "description", "valid_flag", "del_flag", "create_by", "creator_id", "create_time", "update_by", "updater_id", "update_time") VALUES
(1, '1级（绝密）', 1, NULL, NULL, '****', 1, '包含核心银行系统密钥、客户征信原始数据、反洗钱内部情报、监管处罚未公开信息等，一旦泄露将严重危害金融安全和客户权益。', 1, 0, 'test', 2, '2025-09-22 11:29:21', 'test', 2, '2025-09-22 11:29:21'),
(2, '2级（机密）', 1, NULL, NULL, '####', 1, '涉及大额交易记录、客户账户余额、信贷审批信息、风险评估模型参数等关键业务数据，一旦泄露将影响银行经营安全和客户隐私。', 1, 0, 'test', 2, '2025-09-22 11:30:44', 'test', 2, '2025-09-22 11:30:44'),
(3, '3级（秘密）', 2, 2, 10, '****', 1, '涉及客户基本信息（姓名、身份证号、联系方式）、交易流水、产品持有信息等日常业务数据，保留前3位，其余用***替代（如"张三丰"→"张**丰"）。', 1, 0, 'test', 2, '2025-09-22 11:31:05', 'test', 2, '2025-09-22 11:31:05'),
(4, '4级（内部）', 2, 3, 8, '****', 1, '一般内部使用数据，如运维日志、系统配置、一般统计报表等，泄露影响较小但仍需内部保护。脱敏处理部分关键字段，如手机号138****5678、身份证110***********1234。', 1, 0, 'test', 2, '2025-09-22 11:34:28', 'test', 2, '2025-09-22 11:34:28'),
(5, '5级（公开）', 1, NULL, NULL, '****', 1, '可以对外公开的数据，如银行产品介绍、公开财报摘要、营业网点信息等，不涉及客户隐私和商业机密。可直接展示或仅弱化部分字段（如展示城市，不展示精确地址）。', 1, 0, 'test', 2, '2025-09-22 11:34:54', 'test', 2, '2025-09-22 11:34:54');
