(123, 3, 'SQL', 'Kingbase_水位日统计', 153383838261792, 2, 1, 174954643786848, '{\"taskPriority\":\"MEDIUM\",\"workerGroup\":\"default\",\"failRetryTimes\":0,\"failRetryInterval\":1,\"delayTime\":1,\"jobManagerMemory\":\"1G\",\"taskManagerMemory\":\"2G\",\"slot\":1,\"taskManager\":2,\"parallelism\":1,\"yarnQueue\":\"\",\"driverCores\":1,\"driverMemory\":\"512M\",\"numExecutors\":1,\"executorMemory\":\"1G\",\"executorCores\":1,\"typaCode\":\"Kingbase\",\"datasourceId\":5,\"sqlType\":\"0\",\"taskType\":\"SQL\",\"segm\":\"\",\"componentType\":\"51\",\"localParams\":[],\"sql\":\"/* ===========================================================\\r\\n   环境准备（按需修改库名）\\r\\n   =========================================================== */\\r\\n-- 可选：使用你的业务库\\r\\nCREATE DATABASE IF NOT EXISTS hydrology DEFAULT CHARACTER SET utf8mb4;\\r\\nUSE hydrology;\\r\\n\\r\\n/* ===========================================================\\r\\n   1) 报表表（日平均水位）\\r\\n   - 以 (station_code, stat_date) 做唯一键，兼容无维表场景\\r\\n   - 如存在维表，会同步写入 station_id / station_name\\r\\n   =========================...', 'MEDIUM', 0, 1, 0, 1, -1, -1, '【Kingbase 存储过程】查询水位实时数据，生成每日统计报表  ', 108, 1, 0, 'test', 2, '2025-09-30 16:09:14', 'test', 2, '2025-09-30 16:09:14', NULL, 51),
(2066899235819974657, 3, 'SQL', '水水顶顶顶', 1781622153607000, 2, 1, 174954643786848, '{"failRetryTimes":0,"driverCores":1,"executorCores":1,"parallelism":1,"slot":1,"segm":"","sql":"-- 1. 建表\\nCREATE TABLE t_user\\n(\\n    id          INT IDENTITY(1,1) PRIMARY KEY,                      -- 自增主键\\n    username    VARCHAR(50) NOT NULL UNIQUE,                        -- 登录名，唯一\\n    password    VARCHAR(64) NOT NULL,                               -- 密码密文\\n    real_name   VARCHAR(50),                                        -- 真实姓名\\n    email       VARCHAR(100) UNIQUE,                                -- 邮箱，唯一\\n    phone       VARCHAR(20),                                        -- 手机号\\n    status      CHAR(1)   DEFAULT ''1'' CHECK (status IN (''0'', ''1'')), -- 状态 1=启用 0=禁用\\n    create_time TIMESTAMP DEFAULT SYSDATE,                          -- 创建时间\\n    update_time TIMESTAMP DEFAULT SYSDATE                           -- 更新时间\\n);\\n-- 2. 插入示例数据\\nINSERT INTO t_user (username, password, real_name, email, phone, status)\\nVALUES (''zhangsan'', ''e10adc3949ba59abbe56e057f20f883e'', ''张三'', ''zhangsan@demo.com'', ''13800000001'', ''1''),\\n       (''lisi'', ''25d55ad283aa400af464c76d713c...","numExecutors":1,"taskType":"SQL","failRetryInterval":1,"datasourceId":"3","workerGroup":"default","localParams":[],"jobManagerMemory":"1G","componentType":"51","driverMemory":"512M","executorMemory":"1G","executeMode":"","taskPriority":"MEDIUM","taskManagerMemory":"2G","sqlType":"0","typaCode":"DM","delayTime":0,"taskManager":2,"yarnQueue":""}', 'MEDIUM', 0, 1, 0, 0, -1, -1, '', NULL, 1, 0, '超级管理员', 1, '2026-06-16 23:07:29.437', '超级管理员', 1, '2026-06-16 23:55:26.431', NULL, 51),
