INSERT INTO "tax_theme" ("id", "name", "icon", "sort_order", "description", "valid_flag", "del_flag", "create_by", "creator_id", "create_time", "update_by", "updater_id", "update_time", "space_id", "space_code") VALUES
(2, '客户管理', NULL, 1, '聚焦区域水资源总量、水质状况、取用水行为等核心数据，涵盖地表水、地下水、非常规水源的监测与管理信息。通过统一归集与治理，支撑水资源承载能力评估、用水总量控制及可持续利用决策。', 1, 0, 'test', 2, '2025-09-18 15:18:15', 'test', 2, '2025-09-18 15:18:22', 1, 174954643786848),
(3, '账户管理', NULL, 2, '整合降水、水位、流量、流速等实时监测数据，覆盖雨量站、水文站、河道断面等感知节点。实现对流域内水情动态的全面掌握，为洪水预警、调度响应和应急指挥提供及时准确的数据支持。', 1, 0, 'test', 2, '2025-09-18 15:18:44', 'test', 2, '2025-09-18 15:18:44', 1, 174954643786848),
(4, '交易监控', NULL, 3, '汇聚防洪预案、险情上报、应急响应、物资储备、转移安置等全过程管理数据，构建从风险识别到灾后评估的完整数据链条。支撑防汛指挥体系高效运转，提升灾害应对与风险防控能力。', 1, 0, 'test', 2, '2025-09-18 15:18:54', 'test', 2, '2025-09-18 15:18:54', 1, 174954643786848),
(5, '信贷业务', '/profile/2025/09/18/68cbb41fe4b0649f2379b121.png', 4, '管理跨区域、多水源的水量调度方案、调度指令、执行过程及效果反馈数据，涵盖水库、闸坝、泵站等关键工程调度行为。通过数据驱动优化配置流程，保障供水安全与生态需水。', 1, 0, 'test', 2, '2025-09-18 15:21:05', 'test', 2, '2025-09-18 15:26:25', 1, 174954643786848),
(6, '支付清算', '/profile/2025/09/18/68cbb42ae4b0649f2379b122.png', 5, '聚焦农村饮水安全、灌区运行、小型水利工程（如塘坝、机井）等管理数据，覆盖建设、运维、服务全生命周期。支撑农村水利精细化管理和乡村振兴战略实施。', 1, 0, 'test', 2, '2025-09-18 15:24:02', 'test', 2, '2025-09-18 15:26:36', 1, 174954643786848),
